Read the following short program:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
  int a = 1;
  int b = 2;
  int c = 3;
  int *p, *q, *r;
  p = &a;
  q = &b;
  r = &a;

  printf("line 1: %d, %d, %d\n", *p, *q, *r);

