```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 100

int main(int argc, char *argv[]) {
    FILE *f = fopen(argv[1], "r");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    // room for 100 chars, plus one extra char to detect a long line, plus '\0'
    char prev[MAX_LEN + 2];
    char curr[MAX_LEN + 2];
    int first = 1;
    while (fgets(curr, sizeof curr, f) != NULL) {
        // remove the trailing newline, if any
        size_t len = strlen(curr);
        if (len > 0 && curr[len - 1] == '\n') {
            curr[len - 1] = '\0';
            len--;
        }
        if (len > MAX_LEN) {
            fprintf(stderr, "error: line longer than %d characters\n", MAX_LEN);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        if (!first && strcmp(prev, curr) > 0) {
            printf("lines out of order:\n  %s\n  %s\n", prev, curr);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        strcpy(prev, curr);
        first = 0;
    }
    fclose(f);
    printf("lines in input are in order\n");
    exit(EXIT_SUCCESS);
}
```

Tested on the `good` and `bad` files from the transcript, on a last line with no trailing newline, on lines of exactly 100 and 101 characters, and on a missing file.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 80

int main(int argc, char *argv[]) {
    FILE *f = fopen(argv[1], "r");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    // room for 80 chars, plus one extra char to detect a long line, plus '\0'
    char prev[MAX_LEN + 2];
    char curr[MAX_LEN + 2];
    int line_num = 0;
    while (fgets(curr, sizeof curr, f) != NULL) {
        line_num++;
        size_t len = strlen(curr);
        if (len > 0 && curr[len - 1] == '\n') {
            curr[len - 1] = '\0';
            len--;
        }
        if (len > MAX_LEN) {
            fprintf(stderr, "error: line %d is longer than %d characters\n",
                    line_num, MAX_LEN);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        if (line_num > 1 && strlen(prev) > len) {
            printf("lines %d and %d are out of order:\n  %s\n  %s\n",
                   line_num - 1, line_num, prev, curr);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        strcpy(prev, curr);
    }
    fclose(f);
    printf("lines are sorted by length\n");
    exit(EXIT_SUCCESS);
}
```

Tested on sorted and unsorted files, lines of exactly 80 and 81 characters, and a missing file.

questions.prompt:
**Question 5 (10 points): Structs and Storage Allocation**

In Assignment 5 you created linked lists using structs and pointers. As a reminder, here is the definition of the types used in that assignment:

```c
// A single node in a linked list
struct ListNode {
  int data; // the data in this node
  struct ListNode *next; // pointer to the next node
};

// Refer to a linked list with a pointer to the first node
typedef struct ListNode *LinkedList;
```

The "next" pointer in the last node of a list should be null.

Write a function called `deleteSecond` with a parameter of type `LinkedList`. The function should delete the second node of the linked list. Its return value should be the number that was inside the node that was deleted. The function must also free the heap space used for the node being deleted, to prevent a "memory leak".

If the list is empty or has only one element, your function should do nothing and return 0. (These cases aren't shown in the sample code below in order to save paper, but please be sure to include them in your function.)

The header for your `deleteSecond` function should be:

```c
int deleteSecond(LinkedList list)
```

Here is an example of some code using `deleteSecond`, also using the `addToEnd` and `heapReport` functions from Assignment 5:

```c
printf("start of program: "); heapReport();
LinkedList list = NULL;

// create a singleton list
list = addToEnd(list, 10);
printf("heap report for singleton list: "); heapReport();

// Add five more values to the list
list = addToEnd(list, 20);
list = addToEnd(list, 30);
list = addToEnd(list, 40);
list = addToEnd(list, 50);
list = addToEnd(list, 60);
printf("full list: "); printList(list);
printf("heap report for full list: "); heapReport();

// Test deleteSecond
int i;
for (i = 0; i < 5; i++) {
  int val = deleteSecond(list);
  printf("deleted %d, list is ", val); printList(list);
} // end for

printf("heap report after deletions: "); heapReport();
```

Output:

```
start of program: heap use 0
heap report for singleton list: heap use 32
full list: [10,20,30,40,50,60]
heap report for full list: heap use 192
deleted 20, list is [10,30,40,50,60]
deleted 30, list is [10,40,50,60]
deleted 40, list is [10,50,60]
deleted 50, list is [10,60]
deleted 60, list is [10]
heap report after deletions: heap use 32
```

The above example was run on one of the CASLab Linux machines. The exact amount of heap space used might be different on a different computer, but the important thing is that the heap space reported in the two lines "heap report for singleton list" and "heap report after deletions" is the same, which demonstrates that the space used to store all of the deleted nodes was released.

questions.answer:
```c
int deleteSecond(LinkedList list) {
  if (list == NULL || list->next == NULL) {
    return 0;                      // empty or one-element list
  }
  struct ListNode *second = list->next;
  int value = second->data;
  list->next = second->next;       // unlink the second node
  free(second);                    // release its heap space
  return value;
}
```

Checked with the example above plus an empty list and a one-element list; valgrind reports no leaks or errors.

